#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8
KNOCK_DASHBOARD="https://dashboard.knock.app"
KNOCK_CLI=(npx --yes @knocklabs/cli@latest)

banner "Knock CLI access for agents (spec #21)"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Knock: confirm the Development environment exists"
say "Agents push workflows and the email layout to Development only."
open_url "$KNOCK_DASHBOARD"
step "Open the environment switcher in the dashboard."
step "If you only see Production: Settings → Version control → Environments,"
step "and turn on Development."
pause "Press Enter once Development is listed."

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Knock: create a service token"
say "The Knock CLI signs in with a service token (it starts with knock_st_)."
say "Only an account owner or admin can create one."
open_url "$KNOCK_DASHBOARD"
step "Go to Settings → the 'Service tokens' tab → '+ New token'."
step "Name it something like 'cadence-cli-local', then click generate."
warn "Knock shows the token only once, so copy it now."
ask_secret KNOCK_SERVICE_TOKEN "Paste the service token:"
if [[ "$KNOCK_SERVICE_TOKEN" != knock_st_* ]]; then
  warn "That doesn't start with knock_st_. Check you copied the service token, not an API key."
  confirm "Save it anyway?" || { say "Re-run the wizard when you have the right token."; exit 1; }
fi
write_env KNOCK_SERVICE_TOKEN "$KNOCK_SERVICE_TOKEN"
note "The Knock CLI reads KNOCK_SERVICE_TOKEN from the environment automatically."

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Knock: check the CLI can reach your account"
say "Running the Knock CLI with your token (first run downloads it via npx)."
if KNOCK_SERVICE_TOKEN="$KNOCK_SERVICE_TOKEN" "${KNOCK_CLI[@]}" whoami \
   && KNOCK_SERVICE_TOKEN="$KNOCK_SERVICE_TOKEN" "${KNOCK_CLI[@]}" workflow list --environment development; then
  printf '  %s✓ the CLI is signed in and can see Development%s\n' "$GREEN" "$RESET"
else
  warn "The CLI call failed. Check the token and that Development is turned on."
  SKIPPED+=("Knock CLI check failed: re-run scripts/knock-cli-wizard.sh")
fi
pause

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Knock: web-push-fcm channel ID"
say "The app needs the push channel's UUID (not its key) to register browsers."
open_url "$KNOCK_DASHBOARD"
step "Switch to the Development environment."
step "Open the channels list (Integrations → Channels) and click 'web-push-fcm'."
step "Copy the channel's ID, a UUID such as 3f2c…-…"
note "If you can't find it, press Enter on an empty line and paste it into .env later."
ask KNOCK_FCM_CHANNEL_ID "Paste the channel ID:" || true
if [[ -n "${KNOCK_FCM_CHANNEL_ID:-}" ]]; then
  write_env KNOCK_FCM_CHANNEL_ID "$KNOCK_FCM_CHANNEL_ID"
else
  SKIPPED+=("KNOCK_FCM_CHANNEL_ID in .env (needed by the web push tickets)")
fi

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Knock: in-app feed channel ID"
say "The Notification Feed drawer connects to Knock's in-app feed channel by its UUID."
open_url "$KNOCK_DASHBOARD"
step "Switch to the Development environment."
step "Open Integrations → Channels and click the in-app feed channel."
step "Copy the channel's ID, a UUID such as 3f2c…-…"
note "Without it (or KNOCK_PUBLIC_API_KEY / KNOCK_SIGNING_KEY), Cadence runs with no bell and no Feed."
ask KNOCK_FEED_CHANNEL_ID "Paste the channel ID:" || true
if [[ -n "${KNOCK_FEED_CHANNEL_ID:-}" ]]; then
  write_env KNOCK_FEED_CHANNEL_ID "$KNOCK_FEED_CHANNEL_ID"
else
  SKIPPED+=("KNOCK_FEED_CHANNEL_ID in .env (needed by the Notification Feed)")
fi

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Knock: turn on Enhanced security mode"
say "With it on, the browser can only read a Feed with a user token Cadence signed,"
say "so nobody can read someone else's Notifications with the public API key alone."
open_url "$KNOCK_DASHBOARD"
step "Switch to the Development environment."
step "Go to Platform → API keys and turn on 'Enhanced security mode'."
step "If KNOCK_SIGNING_KEY isn't in .env yet, generate a signing key on the same page"
step "and paste it into .env as KNOCK_SIGNING_KEY (the PEM or its base64 form)."
warn "Do the same in Production when the Feed ships there."
pause "Press Enter once Enhanced security mode is on."

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "Development email: DEV_EMAIL_TO"
say "In development every user's Notification email goes to this one address."
say "Development sends from onboarding@resend.dev, which Resend only delivers to"
say "the address your Resend account signed up with, so use that address."
ask DEV_EMAIL_TO "Your Resend account's email address:" || true
if [[ -n "${DEV_EMAIL_TO:-}" ]]; then
  write_env DEV_EMAIL_TO "$DEV_EMAIL_TO"
else
  SKIPPED+=("DEV_EMAIL_TO in .env (without it, development sends no Notification emails)")
fi

# ── Stage 8 ───────────────────────────────────────────────────────────────
stage "Knock: push the workflows and check the emails arrive"
if [[ -z "${DEV_EMAIL_TO:-}" ]]; then
  warn "Skipped: needs DEV_EMAIL_TO from the previous stage."
  SKIPPED+=("Email check: re-run the wizard once DEV_EMAIL_TO is set")
else
  say "Pushing knock/ to Knock Development, then sending each workflow once with"
  say "sample data to $DEV_EMAIL_TO."
  if KNOCK_SERVICE_TOKEN="$KNOCK_SERVICE_TOKEN" npm run --silent knock:push; then
    recipients=$(DEV_EMAIL_TO="$DEV_EMAIL_TO" node -e \
      'console.log(JSON.stringify([{ id: "wizard-email-check", name: "Wizard Check", email: process.env.DEV_EMAIL_TO }]))')
    while IFS=$'\t' read -r workflow actor data; do
      KNOCK_SERVICE_TOKEN="$KNOCK_SERVICE_TOKEN" "${KNOCK_CLI[@]}" workflow run "$workflow" \
        --environment development --recipients "$recipients" --actor "$actor" --data "$data" >/dev/null \
        && note "sent $workflow" || warn "couldn't run $workflow"
    done < <(node -e '
      for (const s of require("./scripts/knock-samples.json"))
        console.log([s.workflow, JSON.stringify(s.actor), JSON.stringify(s.data)].join("\t"));')
    step "Check $DEV_EMAIL_TO: six emails from 'Cadence (dev)' should arrive."
    step "Seat claimed sends no email: it is off by default. That is expected."
    step "Each has a grey page, the Cadence logo, a white card with one button,"
    step "and a two-column footer: 'Why you got this' and 'Your emails'."
    step "The three refund emails show a lock: 'Emails about your refund requests always reach you.'"
    note "Nothing arrived? In Knock (Development) open Logs → Messages. 'Identity not found'"
    note "means the From domain isn't verified in Resend."
    confirm "Did the six emails arrive and look right?" \
      || SKIPPED+=("Notification emails didn't arrive or looked wrong: check Knock Development's message logs")
  else
    warn "npm run knock:push failed. Check KNOCK_SERVICE_TOKEN and that node_modules is installed."
    SKIPPED+=("npm run knock:push failed: fix it and re-run the wizard")
  fi
fi

finish
}

run_wizard "$@"; exit
